using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sends a callback query to a bot and returns an answer. Returns an error with code 502 if the bot fails to answer the query before the query timeout expires
    /// </summary>
    public Task<TdLib.TdApi.Objects.CallbackQueryAnswer> GetCallbackQueryAnswerAsync(long chatId = default, long messageId = default, CallbackQueryPayload payload = default)
    {

           using var activity =  StartCallActivity("GetCallbackQueryAnswerAsync", typeof(GetCallbackQueryAnswer).FullName ?? "GetCallbackQueryAnswerAsync");

           try
           {
             return client.GetCallbackQueryAnswerAsync(chatId, messageId, payload);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
